use super::*;
use semio_framework_os_kernel::{sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteValue,SqliteSnapshotPhase},ArtifactSqliteSnapshot};
fn fixture()->AviSnapshot{store::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
#[test]
fn sqlite_snapshot_avi_owned_payload_codecs_preserve_non_wire_intermediates(){let snapshot=fixture();let pack=<AviSnapshot as store::ArtifactPack>::encode_pack_with(&snapshot,&store::PackEncodeOptions::default()).unwrap();assert_eq!(<AviSnapshot as store::ArtifactPack>::decode_pack(&pack).unwrap(),snapshot);let text=<AviSnapshot as store::ArtifactDsl>::print_dsl(&snapshot);assert_eq!(<AviSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap(),snapshot);}
#[test]
fn sqlite_snapshot_avi_actual_erased_capability_preserves_binary_and_text(){use semio_framework_os_kernel::{io::{ArtifactDialect,IoPayload},sqlite_snapshot::SnapshotEncoding};let snapshot=fixture();let codec=(crate::native_codecs()[0].codec)();let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.avi".into(),standard:"1.0".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(<AviSnapshot as store::ArtifactPack>::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(<AviSnapshot as store::ArtifactDsl>::print_dsl(&snapshot))};let database=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let database=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=(provider.import)(&codec.schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let restored=match restored{IoPayload::Binary(bytes)=><AviSnapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=><AviSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()};assert_eq!(restored,snapshot);}}
fn roundtrip(snapshot:&AviSnapshot)->AviSnapshot{let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();AviSnapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
#[test]
fn sqlite_snapshot_avi_full_neutral_choices_widths_extras_and_empty_state(){let snapshot=fixture();assert_eq!(roundtrip(&snapshot),snapshot);let oracle:serde_json::Value=serde_json::from_str(&store::json::to_json_string(&protocol::ToValue::to_value(&snapshot))).unwrap();assert_eq!(oracle,serde_json::from_str::<serde_json::Value>(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap());let mut empty=AviSnapshot::default();empty.schema="".into();empty.main_header.reserved.clear();assert_eq!(roundtrip(&empty),empty);}
#[test]
fn sqlite_snapshot_avi_independent_sqlite_joins_and_complete_retained_edits(){use std::{io::Write,process::{Command,Stdio}};let mut expected=fixture();let database=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import {Database} from 'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const row=db.query('SELECT h.rc_frame_width,h.quality,b.width,b.colors_important FROM avi_stream s JOIN avi_stream_header h ON h.id=s.id JOIN avi_bitmap_info b ON b.id=s.id').get();if(row.rc_frame_width!==255||row.quality!==-2147483648||row.width!==-2147483648||row.colors_important!==4294967295)throw Error('domain');if(db.query('SELECT channels FROM avi_wave_format').get().channels!==65535||db.query('SELECT hex(data) AS bytes FROM avi_raw_format').get().bytes!=='00FF2A')throw Error('choices');db.run(\"UPDATE avi_stream_header SET quality=-123,strh_extra=X'00FF' WHERE id=1\");db.run(\"UPDATE avi_bitmap_info SET width=88 WHERE id=1\");db.run(\"UPDATE avi_stream_extra SET fourcc='edited 世界' WHERE id=1\");db.run('UPDATE avi_stream_chunk SET keyframe=0 WHERE id=1');db.run('UPDATE avi_main_reserved SET value=99 WHERE ordinal=4');await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.streams[0].strh.quality=-123;expected.streams[0].strh.strh_extra=vec![0,255];if let AviStreamFormat::BitmapInfo{width,..}=&mut expected.streams[0].strf{*width=88;}expected.streams[0].strl_extra[0].fourcc="edited 世界".into();expected.streams[0].chunks[0].keyframe=false;expected.main_header.reserved[4]=99;assert_eq!(AviSnapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);}
#[test]
fn sqlite_snapshot_avi_refuses_invalid_owners_ordinals_choices_widths_and_limits(){let snapshot=fixture();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for(table,column,value)in[("avi_stream",1,SqliteValue::Integer(99)),("avi_stream",2,SqliteValue::Integer(99)),("avi_stream",3,SqliteValue::Text("raw".into())),("avi_stream_chunk",1,SqliteValue::Integer(99)),("avi_stream_chunk",2,SqliteValue::Integer(99)),("avi_stream_chunk",5,SqliteValue::Integer(2)),("avi_stream_header",4,SqliteValue::Integer(65536)),("avi_stream_header",18,SqliteValue::Integer(256)),("avi_main_header",1,SqliteValue::Integer(4294967296)),("avi_bitmap_info",2,SqliteValue::Integer(-2147483649))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=value;assert!(AviSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}for table in["avi_main_header","avi_stream_header","avi_bitmap_info"]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows.clear();assert!(AviSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());assert!(AviSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:0,..SqliteDatabaseLimits::default()})).is_err());}
#[test]
fn sqlite_snapshot_avi_large_intrinsic_copy_and_entities_remain_cancellable(){let controls:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🎛️control.json")).unwrap();let mut snapshot=fixture();snapshot.streams[0].chunks=vec![snapshot.streams[0].chunks[0].clone();controls["entityCount"].as_u64().unwrap() as usize];let cancel_at=controls["cancelAt"].as_u64().unwrap() as usize;let mut reached=false;assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |event|{if event.completed>=cancel_at{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);snapshot=fixture();snapshot.streams[0].strh.strh_extra=vec![255;controls["largeBlobBytes"].as_u64().unwrap() as usize];let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>0&&event.total==0{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{AviSnapshot::from_sqlite_database(&database,&mut control).is_err()});assert!(reached);}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_avi_actual_declaration_preserves_full_owned_intermediate_state(){use semio_framework_os_kernel::{io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}},sqlite_snapshot::SnapshotEncoding};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("AVI SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let snapshot=fixture();let dialect=ArtifactDialect{artifact_kind:"s.stdio.avi".into(),standard:"1.0".into(),subset:"*".into()};let mut phases=Vec::new();let output=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |event|{phases.push(event.phase);true}).await.unwrap();assert_eq!(io_import_sqlite_snapshot::<AviSnapshot>(&dialect,&output.value,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,snapshot);assert!(!phases.iter().any(|phase|matches!(phase,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}

#[test]
fn sqlite_snapshot_avi_owned_encoding_preflight_checks_bounds_before_allocation(){use semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding;for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut snapshot=fixture();snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).unwrap_err().contains("native encoding exceeds file byte limit"));snapshot.streams[0].chunks[0].data=vec![255;131073];let mut reached=false;assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>0{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);}}

#[test]
fn sqlite_snapshot_avi_native_factory_declares_actual_structural_hash(){let value:serde_json::Value=serde_json::from_str(crate::ARTIFACT_DEFINITION_SCHEMA).unwrap();let codec=(crate::native_codecs()[0].codec)();let actual=store::ArtifactCodec::bare::<AviSnapshot,crate::AviMutation>(crate::STDIO_AVI_DOCUMENT_SCHEMA);assert_eq!(semio_framework_hash::hex_lower(&codec.pack_schema_hash),semio_framework_hash::hex_lower(&actual.pack_schema_hash));assert_eq!(semio_framework_hash::hex_lower(&codec.pack_schema_hash),value["codecs"][0]["native_factory"]["pack_schema_hash"].as_str().unwrap());}
